import { getUserRes, useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';

export const useRefreshUserInfo = () => {
  const cachedUserRes = getUserRes();
  const shouldRefresh = cachedUserRes.tbCstmrMastr.priAliasNm !== null;

  return useGetUserInfoQuery({
    enabled: shouldRefresh,
    staleTime: 0,
    throwOnError: false,
    refetchOnMount: shouldRefresh,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
  });
};
